      backup_text =
        "# Sprouts and Shrooms #\n\n\
         # Tic-tac-toe in the night garden: sprouts race shrooms for three in \
         a row. #\n\n\
         type Cell = + Empty + Sprout + Shroom in\n\n\
         # 9 cells, row-major: [0,1,2,3,4,5,6,7,8] #\n\
         type Board = [Cell] in\n\n\
         type Player = + PlayerSprout + PlayerShroom in\n\n\
         type GameStatus =\n\
         + InProgress\n\
         + Won(Player)\n\
         + Draw\n\
         in\n\n\
         type Model = (\n\
         board = Board,\n\
         turn = Player,\n\
         status = GameStatus\n\
         ) in\n\n\
         type Action = + ClickCell(Int) + NewGame in\n\n\
         let emptyBoard: Board =\n\
         [Empty, Empty, Empty,\n\
         Empty, Empty, Empty,\n\
         Empty, Empty, Empty]\n\
         in\n\n\
         let init: Model = (\n\
         board = emptyBoard,\n\
         turn = PlayerSprout,\n\
         status = InProgress\n\
         ) in\n\n\
         let getCell(board: Board, pos: Int): Cell = nth(board, pos) in\n\n\
         let setCell(board: Board, pos: Int, cell: Cell): Board =\n\
         mapi(board, fun (i, c) -> if i == pos then cell else c)\n\
         in\n\n\
         let playerCell(p: Player): Cell =\n\
         case p\n\
         | PlayerSprout => Sprout\n\
         | PlayerShroom => Shroom\n\
         end\n\
         in\n\n\
         let cellStr(c: Cell): String =\n\
         case c\n\
         | Empty => \" \"\n\
         | Sprout => \"\240\159\140\177\"\n\
         | Shroom => \"\240\159\141\132\"\n\
         end\n\
         in\n\n\
         # Three matching non-empty cells win a line #\n\
         let threeInRow(a: Cell, b: Cell, c: Cell): Option =\n\
         case (a, b, c)\n\
         | (Sprout, Sprout, Sprout) => Some(Sprout)\n\
         | (Shroom, Shroom, Shroom) => Some(Shroom)\n\
         | _ => None\n\
         end\n\
         in\n\n\
         let getCells3(board: Board, i: Int, j: Int, k: Int): (Cell, Cell, \
         Cell) =\n\
         (getCell(board, i), getCell(board, j), getCell(board, k))\n\
         in\n\n\
         # The eight ways to win, as cell positions #\n\
         let winningLines: [(Int, Int, Int)] = [\n\
         (0, 1, 2),\n\
         (3, 4, 5),\n\
         (6, 7, 8),\n\
         (0, 3, 6),\n\
         (1, 4, 7),\n\
         (2, 5, 8),\n\
         (0, 4, 8),\n\
         (2, 4, 6)\n\
         ] in\n\n\
         # The first Some in a list, or None if there isn't one #\n\
         let firstSome(options: [Option]): Option =\n\
         fold_left(\n\
         options,\n\
         fun (found, o) ->\n\
         case found\n\
         | Some(c) => Some(c)\n\
         | None => o\n\
         end,\n\
         None\n\
         )\n\
         in\n\n\
         let checkWinner(board: Board): Option =\n\
         firstSome(\n\
         map(winningLines, fun (i, j, k) -> threeInRow(getCells3(board, i, j, \
         k)))\n\
         )\n\
         in\n\n\
         let isFull(board: Board): Bool = for_all(board, fun c -> c != Empty) \
         in\n\n\
         let cellToPlayer(c: Cell): Player =\n\
         case c\n\
         | Sprout => PlayerSprout\n\
         | Shroom => PlayerShroom\n\
         # Unreachable: only a played cell is ever converted #\n\
         | Empty => PlayerSprout\n\
         end\n\
         in\n\n\
         let calcStatus(board: Board): GameStatus =\n\
         case checkWinner(board)\n\
         | Some(c) => Won(cellToPlayer(c))\n\
         | None => if isFull(board) then Draw else InProgress\n\
         end\n\
         in\n\n\
         let nextPlayer(p: Player): Player =\n\
         case p\n\
         | PlayerSprout => PlayerShroom\n\
         | PlayerShroom => PlayerSprout\n\
         end\n\
         in\n\n\
         let isValidMove(model: Model, pos: Int): Bool =\n\
         pos >= 0\n\
         && pos < 9\n\
         && getCell(model.board, pos) == Empty\n\
         && model.status == InProgress\n\
         in\n\n\
         let move(model: Model, pos: Int): Model =\n\
         if isValidMove(model, pos) then\n\
         let newBoard = setCell(model.board, pos, playerCell(model.turn)) in\n\
         (\n\
         board = newBoard,\n\
         turn = nextPlayer(model.turn),\n\
         status = calcStatus(newBoard)\n\
         )\n\
         # An invalid move leaves the board untouched #\n\
         else model\n\
         in\n\n\
         let update(model: Model, action: Action): Model =\n\
         case action\n\
         | ClickCell(pos) => move(model, pos)\n\
         | NewGame => init\n\
         end\n\
         in\n\n\
         # ===== VIEW ===== #\n\n\
         let view(model: Model): HTML =\n\
         let playerName(p: Player): String =\n\
         case p\n\
         | PlayerSprout => \"Sprout\"\n\
         | PlayerShroom => \"Shroom\"\n\
         end\n\
         in\n\
         let statusText: String =\n\
         case model.status\n\
         | InProgress => playerName(model.turn) ++ \"'s turn\"\n\
         | Won(p) => playerName(p) ++ \" wins!\"\n\
         | Draw => \"The plot is full - a draw!\"\n\
         end\n\
         in\n\
         let boardRow(positions: [Int]): HTML =\n\
         Div([Style([(\"display\", \"flex\"), (\"gap\", \"2px\"), \
         (\"margin-bottom\", \"2px\")])],\n\
         map(positions, fun pos ->\n\
         Button(\n\
         [\n\
         OnClick(ClickCell(pos)),\n\
         Style([\n\
         (\"width\", \"72px\"), (\"height\", \"72px\"), (\"font-size\", \
         \"1.8em\"),\n\
         (\"background\", \"var(--T1)\"), (\"border\", \"1px solid \
         var(--BR1)\"),\n\
         (\"border-radius\", \"3px\"), (\"font-family\", \"inherit\"), \
         (\"cursor\", \"pointer\")\n\
         ])\n\
         ],\n\
         [Text(cellStr(getCell(model.board, pos)))]\n\
         )\n\
         )\n\
         )\n\
         in\n\
         Div(\n\
         [Style([(\"max-width\", \"300px\"), (\"margin\", \"0 auto\"), \
         (\"text-align\", \"center\"),\n\
         (\"font-family\", \"var(--code-font)\"), (\"font-size\", \"0.85em\"),\n\
         (\"background\", \"var(--SAND)\"), (\"color\", \"var(--STONE)\"),\n\
         (\"border\", \"1px solid var(--BR1)\"), (\"border-radius\", \"0.4em\"),\n\
         (\"overflow\", \"hidden\")])],\n\
         [\n\
         Div(\n\
         [Style([(\"padding\", \"0.9em 1em 0.8em\"), (\"font-size\", \"1.2em\"),\n\
         (\"font-weight\", \"bold\"), (\"color\", \"var(--BR4)\")])],\n\
         [Text(\"\240\159\140\177 Sprouts and Shrooms \240\159\141\132\")]\n\
         ),\n\
         # The status line is the one place a decided game shows colour #\n\
         Div(\n\
         [Style([(\"padding\", \"0.7em 1em\"), (\"background\", \"var(--T2)\"),\n\
         (\"border-top\", \"1px solid var(--BR1)\"),\n\
         (\"border-bottom\", \"1px solid var(--BR1)\"),\n\
         (\"color\", case model.status\n\
         | Won(_) => \"var(--G0)\"\n\
         | Draw => \"var(--BR3)\"\n\
         | InProgress => \"var(--STONE)\"\n\
         end)])],\n\
         [Text(statusText)]\n\
         ),\n\
         Div(\n\
         [Style([(\"padding\", \"0.7em 1em\")])],\n\
         [\n\
         Div(\n\
         [Style([(\"display\", \"inline-block\")])],\n\
         [boardRow([0, 1, 2]), boardRow([3, 4, 5]), boardRow([6, 7, 8])]\n\
         ),\n\
         Button(\n\
         [\n\
         OnClick(NewGame),\n\
         Style([(\"width\", \"100%\"), (\"margin-top\", \"0.5em\"), \
         (\"padding\", \"0.4em\"),\n\
         (\"background\", \"var(--G0)\"), (\"color\", \"var(--SAND)\"),\n\
         (\"border\", \"1px solid var(--G0)\"), (\"border-radius\", \"3px\"),\n\
         (\"cursor\", \"pointer\"), (\"font-family\", \"inherit\"),\n\
         (\"font-size\", \"0.85em\")])\n\
         ],\n\
         [Text(\"New Plot\")]\n\
         )\n\
         ]\n\
         )\n\
         ]\n\
         )\n\
         in\n\n\
         let subs(_model: Model): Sub = SubNone in\n\n\
         # ===== TESTS ===== #\n\n\
         let play(m: Model, moves: [Int]): Model = fold_left(moves, move, m) \
         in\n\n\
         hint \"the plot starts empty, with sprout to play\"\n\
         test\n\
         for_all(init.board, fun c -> c == Empty) &&\n\
         init.turn == PlayerSprout &&\n\
         init.status == InProgress\n\
         end;\n\n\
         hint \"a move places a marker and passes the turn\"\n\
         test\n\
         let m = move(init, 0) in\n\
         getCell(m.board, 0) == Sprout && m.turn == PlayerShroom\n\
         end;\n\n\
         hint \"an occupied cell can't be replayed\"\n\
         test\n\
         # Sprout plays 0, then Shroom tries the same cell #\n\
         let m = play(init, [0, 0]) in\n\
         getCell(m.board, 0) == Sprout\n\
         && m.turn == PlayerShroom\n\
         end;\n\n\
         hint \"three in a row wins, and the plot then closes\"\n\
         test\n\
         let m = play(init, [0, 3, 1, 4, 2, 5]) in\n\
         case m.status | Won(PlayerSprout) => getCell(m.board, 5) == Empty | _ \
         => false end\n\
         end;\n\n\
         hint \"a full plot with no line is a draw\"\n\
         test\n\
         let m = play(init, [0, 1, 2, 5, 3, 6, 4, 8, 7]) in\n\
         case m.status | Draw => true | _ => false end\n\
         end;\n\n\
         hint \"off-board positions are rejected\"\n\
         test\n\
         for_all(move(init, 9).board, fun c -> c == Empty)\n\
         && for_all(move(init, -1).board, fun c -> c == Empty)\n\
         end;\n\n\
         hint \"new game resets\"\n\
         test\n\
         let m = update(move(init, 0), NewGame) in\n\
         for_all(m.board, fun c -> c == Empty) && m.turn == PlayerSprout\n\
         end;\n\n\
         # Nothing here issues a command, so `update` returns a bare Model and \
         is #\n\
         # lifted into the (Model, Cmd) shape the app tuple expects. #\n\n\
         let noCmd(f: (Model, Action) -> Model): (Model, Action) -> (Model, \
         Cmd) =\n\
         fun (model, action) -> (f(model, action), CmdNone)\n\
         in\n\n\
         ^^html_sidebar((init, noCmd(update), view, subs))\n";
      refractors = "()";
    } )
